coding.solution:
class DataFactory:
    def __init__(self, run_id, worker):
        self.run_id = run_id
        self.worker = worker
        self.n = 0

    def user(self, role='customer'):
        self.n += 1
        return {'email': f'qa+{self.run_id}-w{self.worker}-{self.n}@example.test', 'role': role}

tests.code:
f = DataFactory('r42', 3)
assert f.user()['email'] == 'qa+r42-w3-1@example.test'
assert f.user('admin') == {'email': 'qa+r42-w3-2@example.test', 'role': 'admin'}
